	rows, err := s.DB.Query(r.Context(), `SELECT event_type,channels,enabled FROM notification_preferences WHERE user_id=$1`, p.UserID)
	if err != nil {
		writeError(w, 500, "query_failed", "알림 설정을 조회하지 못했습니다.")
