		var enabled bool
		if rows.Scan(&eventType, &channels, &enabled) == nil {
			stored[eventType] = map[string]any{"event_type": eventType, "channels": channels, "enabled": enabled}
		}
	}
	rows.Close()
	items := make([]map[string]any, 0, len(eventCatalog))
